  ('hanslbaunk', 'Hanslbaunk', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Hanselbank', '[{"kategorie": "wörtlich", "text": "\"Heinzelmännchenbank\" (Determinativkompositum aus \"Hansel\"=Verballhornung von \"Heinzelmännchen\" und \"Bank\"=\"Werkbank\")"}, {"kategorie": "techn.", "text": "Traditionelle Holzbearbeitungsbank mit Fußhebel, Schnitzbank, [[Heinzelbank]]"}, {"kategorie": "hist.", "text": "Die sogenannte Hanselbank (eigentlich: [[Heinzelbank]]) ist ein historisches Werkzeug zum Fixieren von Holz bei Schnitz-, Schälarbeiten oder der Herstellung von Stäben. Der Handwerker sitzt rittlings auf der Bank und bedient mit dem Fuß eine Hebelstange („Sterze“), die über einen schweren hölzernen Klemmkopf das Werkstück gegen eine schräge Auflage presst. Dadurch bleibt das Holz stabil, um mit einem Reifmesser zweihändig und präzise bearbeitet zu werden – ganz ohne Zwingen oder Schraubstöcke"}, {"kategorie": "hist.", "text": "Der Name „Hanselbank“ leitet sich von den \"Heinzeln\", also \"Heinzelmännchen\" ab – jenen kleinen, fleißigen Kobolden aus der Sage, die nachts heimlich Handwerksarbeiten verrichteten. Die Bank gilt als Sinnbild für praktisches, stilles Handwerk"}, {"kategorie": "hist.", "text": "Besonders alte Exemplare zeigen am Klemmkopf oder am Gestell oft eine geschnitzte Figur eines Heinzelmännchens – als dekoratives Detail und augenzwinkernde Hommage an die sagenhaften Helfer."}]'::jsonb, ''),
  ('heinzlbaunk', 'Heinzlbaunk', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Heinzelbank', '[{"kategorie": "wörtlich", "text": "\"Heinzelmännchenbank\" (Determinativkompositum aus \"Heinzel\"=\"Heinzelmännchen\" und \"Bank\"=\"Werkbank\")"}, {"kategorie": "techn.", "text": "Traditionelle Holzbearbeitungsbank mit Fußhebel, Schnitzbank, [[Hanselbank]]"}, {"kategorie": "hist.", "text": "Die sogenannte Heinzelbank ist ein historisches Werkzeug zum Fixieren von Holz bei Schnitz-, Schälarbeiten oder der Herstellung von Stäben. Der Handwerker sitzt rittlings auf der Bank und bedient mit dem Fuß eine Hebelstange („Sterze“), die über einen schweren hölzernen Klemmkopf das Werkstück gegen eine schräge Auflage presst. Dadurch bleibt das Holz stabil, um mit einem Reifmesser zweihändig und präzise bearbeitet zu werden – ganz ohne Zwingen oder Schraubstöcke"}, {"kategorie": "hist.", "text": "Der Name „Heinzelbank“ leitet sich von den Heinzelmännchen ab – jenen kleinen, fleißigen Kobolden aus der Sage, die nachts heimlich Handwerksarbeiten verrichteten. Die Bank gilt als Sinnbild für praktisches, stilles Handwerk"}, {"kategorie": "hist.", "text": "Besonders alte Exemplare zeigen am Klemmkopf oder am Gestell oft eine geschnitzte Figur eines Heinzelmännchens – als dekoratives Detail und augenzwinkernde Hommage an die sagenhaften Helfer."}]'::jsonb, ''),
